code.cpp:
class Solution {
public:
    int arraySign(vector<int>& nums) {
        int negCount = 0;
        for (int num : nums) {
            if (num == 0) {
                return 0;
            }
            if (num < 0) {
                negCount++;
            }
        }
        return (negCount % 2 == 0) ? 1 : -1;
    }
};
